{"title": "Events per minute", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "Events per minute",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "@timestamp",
      "index": "logs-mcpolis-*",
      "body": {
        "size": 0,
        "aggs": {
          "buckets": {
            "date_histogram": {
              "field": "@timestamp",
              "fixed_interval": "1m",
              "min_doc_count": 0
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.buckets.buckets"
    }
  },
  "mark": {
    "type": "line",
    "interpolate": "step-after",
    "point": true
  },
  "encoding": {
    "x": {
      "field": "key",
      "type": "temporal",
      "title": null
    },
    "y": {
      "field": "doc_count",
      "type": "quantitative",
      "title": "Events / min"
    },
    "tooltip": [
      {
        "field": "key",
        "type": "temporal",
        "title": "Time"
      },
      {
        "field": "doc_count",
        "type": "quantitative",
        "title": "Events"
      }
    ]
  }
}"}}

{"title": "Top 10 events by frequency", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "Top 10 events by frequency",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "@timestamp",
      "index": "logs-mcpolis-*",
      "body": {
        "size": 0,
        "aggs": {
          "top_events": {
            "terms": {
              "field": "event",
              "size": 10
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.top_events.buckets"
    }
  },
  "mark": "bar",
  "encoding": {
    "y": {
      "field": "key",
      "type": "nominal",
      "sort": "-x",
      "title": "Event"
    },
    "x": {
      "field": "doc_count",
      "type": "quantitative",
      "title": "Count"
    },
    "tooltip": [
      {
        "field": "key",
        "type": "nominal",
        "title": "Event"
      },
      {
        "field": "doc_count",
        "type": "quantitative",
        "title": "Count"
      }
    ]
  }
}"}}
